DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.complete_lesson_exercise(uuid,text)'::regprocedure) INTO definition; definition:=replace(definition,'FROM public.language_profiles WHERE user_id=_uid','FROM public.course_enrollments WHERE user_id=_uid'); definition:=replace(definition,'course_type=_lesson.course AND (','course_type=_lesson.course AND onboarding_completed AND ('); EXECUTE definition; SELECT pg_get_functiondef('public.submit_survey(text,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'submit_survey(p_language text, p_answers jsonb)','submit_survey(p_language text, p_answers jsonb, p_course text)'); definition:=replace(definition,'enrollment public.language_profiles','enrollment public.course_enrollments'); definition:=replace(definition,'FROM public.language_profiles WHERE user_id=auth.uid() AND language=p_language AND onboarding_completed=true','FROM public.course_enrollments WHERE user_id=auth.uid() AND language=p_language AND course_type=p_course AND onboarding_completed=true'); EXECUTE definition; END $$;
REVOKE ALL ON FUNCTION public.submit_survey(text,jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_survey(text,jsonb,text) TO authenticated,service_role;